// Hand-written. Not generated by Speakeasy.
//
// Hands the current resource schemas to the stateupgraders package.
//
// Speakeasy registers the upgraders without a PriorSchema, so they receive raw
// JSON and must re-encode against the current schema themselves. They cannot
// import the provider package to get it -- the provider imports them, and Go
// forbids the cycle -- so the dependency is inverted at runtime instead: this
// file runs during package init and pushes the schema types across.
//
// Keep the keys here in step with the entity names the upgraders pass to
// upgrade(). TestStateUpgradeSchemasAreRegistered guards that.
package provider

import (
	"context"

	"github.com/authlete/terraform-provider-authlete/internal/stateupgraders"
	"github.com/hashicorp/terraform-plugin-framework/resource"
)

func init() {
	registerStateUpgradeSchemas(context.Background())
}

func registerStateUpgradeSchemas(ctx context.Context) {
	for entity, r := range map[string]resource.Resource{
		"service": NewServiceResource(),
		"client":  NewClientResource(),
	} {
		resp := &resource.SchemaResponse{}
		r.Schema(ctx, resource.SchemaRequest{}, resp)
		if resp.Diagnostics.HasError() {
			// A broken schema fails loudly everywhere else; swallowing it here
			// only avoids a panic during package init.
			continue
		}
		stateupgraders.RegisterSchemaType(entity, resp.Schema.Type().TerraformType(ctx))
	}
}
